#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Embed a .lua file into a C++ raw-string constant, between generated markers.

Specter.Internal ships its Lua layer as a raw string literal (the DLL cannot
read files at runtime), but the Lua source is edited and syntax-checked with
`luac`. This script keeps the two in sync so the .lua stays the single source
of truth.

Usage:
    python3 tools/embed_lua.py            # embed specter_init.lua
    python3 tools/embed_lua.py --check    # verify the C++ is up to date (CI)

Marker block in the .cpp:

    // >>> BEGIN specter_init.lua (generated by tools/embed_lua.py) - do not edit
    ...
    // <<< END specter_init.lua
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
LUA = ROOT / "src/Specter.Internal/features/specter_init.lua"
CPP = ROOT / "src/Specter.Internal/features/lua_console.cpp"

BEGIN = "// >>> BEGIN specter_init.lua (generated by tools/embed_lua.py) - do not edit"
END = "// <<< END specter_init.lua"
DELIM = 'R"lua('
CLOSE = ')lua";'


def build_block(lua_src: str) -> str:
    if CLOSE[:-1] in lua_src or ')lua"' in lua_src:
        raise SystemExit("lua source contains the raw-string terminator )lua\"")
    return "\n".join([
        BEGIN,
        "// Source: src/Specter.Internal/features/specter_init.lua",
        "// Edit the .lua, then re-run: python3 tools/embed_lua.py",
        "constexpr char kSpecterInit[] =",
        DELIM,
        lua_src.rstrip("\n"),
        CLOSE,
        END,
    ])


def main() -> int:
    check_only = "--check" in sys.argv

    lua_src = LUA.read_text(encoding="utf-8")
    block = build_block(lua_src)
    cpp = CPP.read_text(encoding="utf-8")

    start = cpp.find(BEGIN)
    end = cpp.find(END)
    if start == -1 or end == -1 or end < start:
        raise SystemExit(f"markers not found in {CPP}")

    current = cpp[start:end + len(END)]
    if current == block:
        print("up to date (no change)")
        return 0
    if check_only:
        print("OUT OF DATE: run python3 tools/embed_lua.py")
        return 1

    CPP.write_text(cpp[:start] + block + cpp[end + len(END):], encoding="utf-8")
    n = lua_src.count("\n") + 1
    print(f"embedded {LUA.name} ({n} lines) into {CPP.name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
